UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Administer Thrombolysis","body":"**Common local-protocol option:** [Tenecteplase](#/drug/tenecteplase/stroke) 0.25 mg/kg IV bolus (max 25 mg) — single dose over 5 seconds.\n\n**Alternative / standard option:** [Alteplase](#/drug/alteplase/stroke) 0.9 mg/kg IV (max 90 mg) — 10% bolus over 1 min, remainder over 60 min.\n\nTenecteplase has guideline support in eligible AIS patients and is operationally simpler, especially when EVT transfer is possible. Use the agent required by local stroke protocol.\n\n[Patient Consent Info](#/info/stroke-consent)\n\n**Post-thrombolysis orders:**\n• BP <180/105 × 24h ([Labetalol](#/drug/labetalol/stroke) or [Nicardipine](#/drug/nicardipine/stroke))\n• Neuro checks q15min × 2h, then q30min × 6h, then q1h × 16h\n• No antithrombotics × 24h\n• No arterial/central lines, NG tube, or Foley × 24h if possible\n• Any neuro decline → emergent NCCT","citation":[1,4,5],"next":"stroke-lvo-check","treatment":{"firstLine":{"drug":"Tenecteplase","dose":"0.25 mg/kg","route":"IV bolus","frequency":"Once","duration":"Single dose over 5 seconds","notes":"Max 25 mg"},"alternative":{"drug":"Alteplase","dose":"0.9 mg/kg","route":"IV","frequency":"Once","duration":"10% bolus over 1 min, remainder over 60 min","notes":"Max 90 mg"},"monitoring":"BP <180/105 x 24h. Neuro checks q15min x 2h, then q30min x 6h, then q1h x 16h. Any decline = emergent NCCT."},"summary":"Tenecteplase 0.25 mg/kg single bolus where local protocol supports it, or alteplase 0.9 mg/kg — BP <180/105 x24h, no antithrombotics x24h","safetyLevel":"critical"}'::jsonb
